import pytest

from bedrock_protocol import v1001, v2168

EMPTY_ITEM_BLOB = bytes(10)

# generated by gophertunnel 6353c49:
# packet.AddItemActor{EntityUniqueID: 1, EntityRuntimeID: 2,
#   Item: protocol.ItemInstance{Stack: protocol.ItemStack{ItemType: protocol.ItemType{NetworkID: 5}, Count: 1}},
#   Position: mgl32.Vec3{1, 2, 3}, Velocity: mgl32.Vec3{4, 5, 6},
#   EntityMetadata: protocol.EntityMetadata{38: float32(0.5)}, FromFishing: true}
V1001 = bytes.fromhex(
    "02020a01000000000a000000000000000000000000803f0000004000004040000080400000a0400000c0400126030000003f01"
)

# generated by gophertunnel b8bd735:
# packet.AddItemActor{EntityUniqueID: 1, EntityRuntimeID: 2,
#   Item: protocol.ItemInstance{Stack: protocol.ItemStack{ItemType: protocol.ItemType{NetworkID: 5}, Count: 1}},
#   Position: mgl32.Vec3{1, 2, 3}, Velocity: mgl32.Vec3{4, 5, 6},
#   EntityMetadata: protocol.EntityMetadata{38: float32(0.5)}, FromFishing: true}
V2168 = bytes.fromhex(
    "0202050001000000000a000000000000000000000000803f0000004000004040000080400000a0400000c040012603030000003f01"
)

GOLDENS = [
    pytest.param(
        v1001.AddItemActorPacket(
            id=1,
            runtime_id=2,
            item=v1001.NetworkItemStackDescriptor(id=5, stack_size=1, user_data_buffer=EMPTY_ITEM_BLOB),
            pos=v1001.Vec3(x=1.0, y=2.0, z=3.0),
            velocity=v1001.Vec3(x=4.0, y=5.0, z=6.0),
            data=v1001.SynchedActorData.CopyableDataList(
                data=[v1001.DataItemEntry(id=38, payload=v1001.DataItemFloatPayload(value=0.5))]
            ),
            is_from_fishing=True,
        ),
        V1001,
        id="v1001",
    ),
    pytest.param(
        v2168.AddItemActorPacket(
            id=1,
            runtime_id=2,
            item=v2168.SerializedNetworkItemStackDescriptor(id=5, stack_size=1, user_data_buffer=EMPTY_ITEM_BLOB),
            pos=v2168.Vec3(x=1.0, y=2.0, z=3.0),
            velocity=v2168.Vec3(x=4.0, y=5.0, z=6.0),
            data=v2168.SynchedActorData.CopyableDataList(
                data=[v2168.DataItemEntry(id=38, payload=v2168.DataItemFloatPayload(value=0.5))]
            ),
            is_from_fishing=True,
        ),
        V2168,
        id="v2168",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_add_item_actor_is_packet_15(version):
    assert version.packets[15] is version.AddItemActorPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_add_item_actor_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_add_item_actor_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_add_item_actor_2168_body_is_two_bytes_longer_than_1001():
    assert len(V2168) == len(V1001) + 2


def test_add_item_actor_2168_body_leaves_trailing_bytes_at_1001():
    with pytest.raises(ValueError, match="trailing bytes"):
        v1001.AddItemActorPacket.from_bytes(V2168)


def test_add_item_actor_1001_body_is_rejected_at_2168():
    with pytest.raises(ValueError, match="at byte"):
        v2168.AddItemActorPacket.from_bytes(V1001)
